package algoexpert.easy.binary_search;
import java.util.*;

// Approach: Iterative binary search.
class Solution1 {
    public static int binarySearch(int[] A, int v) {
        var N = A.length;

        int lo = 0, hi = N - 1;

        while(lo <= hi) {
            var mid = lo + (hi - lo) / 2;

            if      (v < A[mid])  { hi = mid - 1; }
            else if (A[mid] < v)  { lo = mid + 1; }
            else                    { return mid;  }
        }

        return -1;
    }
}

package algoexpert.easy.binary_search;
import java.util.*;

// Approach: Iterative, compareTo-based.
class Solution2 {
    public static int binarySearch(int[] A, int v) {
        var N = A.length;

        var lo = 0;
        var hi = N - 1;

        while(lo <= hi) {
            var mid = lo + (hi - lo) / 2;
            var cmp = Integer.valueOf(v).compareTo(A[mid]);

            if     (cmp < 0) { hi = mid - 1; }
            else if(0 < cmp) { lo = mid + 1; }
            else             { return mid; }
        }

        return -1;
    }
}

package algoexpert.medium.search_in_sorted_matrix;
import java.util.*;

// Approach: Row-by-row linear scan with early break.
class Solution1 {
    public static int[] searchInSortedMatrix(int[][] M, int v) {
        var R = M.length;
        var C = M[0].length;

        for(var r = R - 1; 0 <= r; r--) {
            for(var c = 0; c < C; c++) {
                var cmp = Integer.valueOf(M[r][c]).compareTo(v);

                if      (cmp < 0) { continue; }
                else if (0 < cmp) { break;  }
                else              { return new int[] { r, c }; }
            }
        }

        return new int[] { -1, -1 };
    }
}

package algoexpert.medium.search_in_sorted_matrix;
import java.util.*;

// Approach: Start top-right, eliminate row or column each step.
class Solution2 {
    public static int[] searchInSortedMatrix(int[][] M, int v) {
        var R = M.length;
        var C = M[0].length;

        var idx = new int[] { 0, C - 1 };

        while(idx[0] < R && 0 <= idx[1]) {
            var t = M[idx[0]][idx[1]];

            if      (t < v) { idx[0]++; }
            else if (v < t) { idx[1]--; }
            else            { return idx; }
        }

        return new int[] { -1, -1 };
    }
}
